package dev.shadw.asgard.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Warg with its own model and texture. Generated by shadw-mod mob. */
public class WargRenderer extends MobRenderer<Warg, WargModel.State, WargModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("asgard", "textures/entity/warg.png");

	public WargRenderer(EntityRendererProvider.Context context) {
		super(context, new WargModel(context.bakeLayer(WargModel.LAYER)), 0.9F);
	}

	@Override
	public WargModel.State createRenderState() {
		return new WargModel.State();
	}

	@Override
	public void extractRenderState(Warg entity, WargModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
		state.airborne = !entity.onGround() && !entity.isNoAi();        // a mob with its AI off is posed, not flying
	}

	@Override
	public ResourceLocation getTextureLocation(WargModel.State state) {
		return TEXTURE;
	}
}
